package com.example.kafka.config; import org.springframework.context.annotation.*; import org.springframework.security.config.*; import org.springframework.security.web.*; import org.springframework.security.config.annotation.web.builders.*; @Configuration public class SecurityConfig{ @Bean SecurityFilterChain filter(HttpSecurity h) throws Exception { return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/**").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build(); }}